css='''@font-face{font-family:Preahvihear;src:url(assets/Preahvihear-Regular.ttf);font-weight:400;font-display:block}*{box-sizing:border-box;margin:0;padding:0;font-family:Preahvihear;font-weight:400;font-style:normal;font-synthesis:none}html,body,.slide{width:1080px;height:1350px;background:#1A1A1A}.slide{position:relative;overflow:hidden;color:#fff}.photo{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.shade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.96),rgba(0,0,0,.88) 30%,rgba(0,0,0,.60) 35%,rgba(0,0,0,.15) 42%,transparent 49%)}.bottom-shade{position:absolute;inset:0;background:linear-gradient(180deg,transparent 71%,rgba(0,0,0,.4) 77%,rgba(0,0,0,.91) 87%,rgba(0,0,0,.96) 100%)}.copy{position:absolute;left:84px;right:84px;top:96px;z-index:3}.headline{font-size:65px;line-height:1.15;letter-spacing:-.6px}.headline span{display:block}.headline span:last-child{color:#04ADC3}.cover .headline{font-size:76px;line-height:1.14;letter-spacing:-1px}.body{font-size:32px;line-height:1.4;margin-top:27px}.cover .body{font-size:36px;line-height:1.38;margin-top:28px}.prompt{display:table;max-width:912px;background:#04ADC3;color:#1A1A1A;border-radius:24px;font-size:27px;line-height:1.4;padding:18px 24px;margin-top:28px}.cover .prompt{font-size:28px}.scene-label{position:absolute;left:84px;right:84px;top:1050px;font-size:25px;line-height:1.4;z-index:3}.results{position:absolute;left:84px;right:84px;top:1110px;display:flex;gap:22px;z-index:3}.result{background:#fff;color:#1A1A1A;border-radius:20px;padding:18px 22px;font-size:24px;line-height:1.35;display:flex;gap:14px;align-items:center;flex:1}.result svg{width:24px;height:24px;flex:none}.footer{position:absolute;left:84px;right:84px;bottom:92px;display:flex;justify-content:space-between;font-size:23px;z-index:5}.trail{position:absolute;left:84px;right:84px;bottom:38px;display:flex;gap:14px}.trail i{height:3px;background:rgba(255,255,255,.2);flex:1}.trail i.on{background:#04ADC3}.closing .body{font-size:30px}.closing .headline{font-size:62px}.closing .prompt{background:#fff}.brand-cta{position:absolute;left:84px;right:84px;top:1082px;border-radius:20px;background:#fff;color:#1A1A1A;padding:20px 28px;display:flex;align-items:center;gap:38px;z-index:3;font-size:34px;line-height:1.4}.brand-cta img{width:178px;height:71px;object-fit:contain}.cover .scene-label{top:1050px}.cover .results{top:1110px}.cover .result{font-size:23px;padding:16px 20px}.cover .copy{top:84px}.closing .brand-cta{top:1082px}.brand-logo{width:178px;height:71px;flex:none}.brand-logo path[transform^="matrix(1,0,0,-1,250.92774"]{fill:#1A1A1A}.slide-8 .scene-label{display:none}.cover .shade{background:linear-gradient(180deg,rgba(0,0,0,.96),rgba(0,0,0,.9) 34%,rgba(0,0,0,.5) 42%,transparent 51%)}.prop-text{position:absolute;z-index:2;color:#1A1A1A}.record{left:123px;top:709px;width:274px;transform:rotate(-2deg);font-size:28px;line-height:1.4}.record small{font-size:20px;color:#5A6262;display:block}.record strong{font-size:44px;display:block;margin:14px 0 28px}.record em{font-size:27px;display:block;color:#A44141;border-top:2px solid #CFC5B8;padding-top:22px}.phone-note{left:245px;top:620px;width:155px;transform:matrix(1,.04,.18,1,0,0);transform-origin:top left;font-size:22px;line-height:1.4}.phone-note small{font-size:19px;display:block;padding-bottom:20px}.phone-note p{background:#DDF3F7;border-radius:15px;padding:12px 10px}.phone-note .sent{display:block;color:#286F5D;font-size:19px;margin-top:22px}.tablet-note{left:272px;top:846px;width:145px;transform:matrix(1,-.04,.52,.85,0,0);transform-origin:top left;font-size:25px;line-height:1.4}.tablet-note small{display:block;font-size:18px}.tablet-note p{margin-top:15px;color:#286F5D}'''
tick='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12l5 5L20 5" fill="none" stroke="#2B907F" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>'
wait='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9" fill="none" stroke="#8A6A22" stroke-width="2"/><path d="M12 6v6l4 2" fill="none" stroke="#8A6A22" stroke-width="2"/></svg>'
for i,s in enumerate(data['slides']):
 n=i+1;title=''.join('<span>'+html.escape(x)+'</span>' for x in H[i]);body='<br>'.join(html.escape(x) for x in s['body'])
 out='<div class="results">'+''.join('<p class="result">'+(wait if n in [2,3,4,6] and j==1 else tick)+html.escape(x)+'</p>' for j,x in enumerate(results[i]))+'</div>' if n<8 else '<div class="brand-cta">'+logo+'<span>Put ART to work.</span></div>'
 props={1:'<div class="prop-text record"><small>EXPECTED DELIVERY</small><strong>Tuesday</strong><em>Friday.<br>Still not received.</em></div>',4:'<div class="prop-text phone-note"><small>Supplier follow-up</small><p>Please confirm the revised delivery date.</p><span class="sent">Follow-up sent</span></div>',5:'<div class="prop-text tablet-note"><small>SUPPLIER REPLY</small><p>Response<br>tracked</p></div>'}.get(n,'')
 doc='<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=1080,height=1350"><style>'+css+'</style></head><body><main class="slide '+('cover' if n==1 else 'closing' if n>=6 else 'task')+' slide-'+str(n)+'"><img class="photo" src="assets/scene-'+f'{n:02}'+'.png" alt="'+html.escape(labels[i])+'"><div class="shade"></div><div class="bottom-shade"></div><section class="copy"><h1 class="headline">'+title+'</h1><p class="body">'+body+'</p>'+('<p class="prompt">'+html.escape(prompts[i])+'</p>' if n<8 else '')+'</section>'+props+'<p class="scene-label">'+html.escape(labels[i])+'</p>'+out+'<footer class="footer"><span>@arealtimetech</span><span>'+f'{n:02} / 08'+'</span></footer><div class="trail">'+''.join('<i class="'+('on' if k<n else '')+'"></i>' for k in range(8))+'</div></main></body></html>'
 (P/'slides'/f'slide-{n:02}.html').write_text(doc)
